public class Video
{
    public Guid Id { get; } = Guid.NewGuid();
    public string Title { get; set; }
    public string Description { get; set; }
    public string StreamUrl { get; set; }
    public TimeSpan Duration { get; set; }
    public List<string> Genres { get; } = new();
    public DateTime AddedAt { get; } = DateTime.UtcNow;
}

public class WatchProgress
{
    public Guid UserId { get; set; }
    public Guid VideoId { get; set; }
    public TimeSpan Position { get; set; }
    public DateTime LastWatched { get; set; } = DateTime.UtcNow;

    public void Update(TimeSpan newPosition)
    {
        Position = newPosition;
        LastWatched = DateTime.UtcNow;
    }
}

public class StreamingService
{
    public async Task<Stream> GetStreamAsync(Guid videoId, Guid userId)
    {
        var video = _videos[videoId];
        var progress = _progress.Get(userId, videoId);
        var startPosition = progress?.Position ?? TimeSpan.Zero;
        return await _cdn.GetStreamAsync(video.StreamUrl, startPosition);
    }
}
